/** 13특성 → 상승 log-odds. NaN은 학습 시 분기로 처리. */
export const predictMacroLogOdds = (feats: readonly number[]): number => {
  let s = MACRO_BASELINE;
  for (const t of MACRO_TREES) {
    let node = 0;
    for (let d = 0; d < 64; d++) {
      if (t.l[node] < 0) break;
      const x = feats[t.f[node]];
      const goLeft = !Number.isFinite(x) ? t.ml[node] : x <= t.th[node];
      node = goLeft ? t.l[node] : t.r[node];
    }
    s += t.v[node];
  }
  return s;
};
